    "gh.title": "Parking info",
    "gh.lead": "Everything you need to know about parking at the Matterhorn Terminal in Täsch and reaching car-free Zermatt — how to arrive, charging your electric car and how the shuttle train works.",
    "gh.banner": "Zermatt is car-free. Every car stops in Täsch: park at the Matterhorn Terminal and continue by shuttle train or taxi.",
    "gh.car.d": "Drive to Täsch on the valley road, park in the covered terminal and hop on the train. See the route and the height limit.",
    "gh.charging.d": "131 charging stations at the terminal. Reserve a charging bay with your space and top up while you're in Zermatt.",
    "gh.train.d": "The shuttle train links Täsch and Zermatt in about 12 minutes, roughly every 20 minutes. Tickets, timetable and luggage.",
