    "car.h1": "Arriving by car",
    "car.lead": "How to drive to the Matterhorn Terminal in Täsch and where to leave the car for Zermatt.",
    "car.p1": "Zermatt is car-free, so every road trip to the Matterhorn ends in Täsch. From the Rhône valley you follow the cantonal road up through Visp, St. Niklaus and Randa; the Matterhorn Terminal sits right beside Täsch station at the end of the valley road. Set your sat-nav to “Matterhorn Terminal Täsch” and it takes you straight to the entrance.",
    "car.h2a": "Parking at the terminal",
    "car.p2": "The terminal is a covered multi-storey car park with around 2,100 spaces. When you book online your licence plate is stored, so the barrier opens automatically on arrival and you drive straight to a space — there is no paper ticket to keep. Book “Parking” for a standard space, or “Parking with e-charging station” if your car needs to charge.",
    "car.callout": "book online before you set off. Your plate is recognised at the barrier, so you skip the pay machines on the way in and out.",
    "car.h2b": "The height limit",
    "car.p3": "Maximum height for vehicles is 2.30 metres, which covers ordinary cars, estates and most SUVs once a roof box is removed. Taller vehicles and motorhomes cannot use the covered garage — the coaches & groups page has the alternatives for oversized vehicles.",
    "car.h2c": "From the car to Zermatt",
    "car.p4": "The shuttle-train platform is a two-minute walk from the garage. Trains to car-free Zermatt run about every 20 minutes and take around 12 minutes; taxis and hotel electro-shuttles also pick up at the terminal.",
    "car.f1k": "Car park",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Spaces",
    "car.f2v": "≈ 2,100, covered",
    "car.f3k": "Max height",
    "car.f3v": "2.30 m",
    "car.f4k": "To Zermatt",
    "car.f4v": "Shuttle train, ≈ 12 min",
    "chg.h1": "Electric vehicles & charging",
    "chg.lead": "Charging your electric car while you visit Zermatt, and how to reserve a charging bay.",
    "chg.p1": "The Matterhorn Terminal is one of the largest charging locations in the Alps, with 131 charging stations built into the covered car park. The stations deliver up to 22 kW (AC) with a fixed cable and a Type 2 plug, so most electric cars can charge comfortably while you are up in Zermatt.",
    "chg.h2a": "Reserving a charging bay",
    "chg.p2": "When you book, choose “Parking with e-charging station” instead of standard parking. That reserves a space next to a charger for the whole of your stay, so you don't have to hunt for a free unit when you arrive.",
    "chg.callout": "pick “Parking with e-charging station” at the first step of the booking form to guarantee a charger for your dates.",
    "chg.h2b": "Paying for the energy",
    "chg.p3": "Your reservation covers the parking space and the charging bay. The energy you actually draw is billed separately at the station by QR code — credit card, TWINT, Apple Pay and Google Pay are all accepted — so you only ever pay for the electricity you use.",
    "chg.f1k": "Stations",
    "chg.f1v": "131, in the garage",
    "chg.f2k": "Power",
    "chg.f2v": "Up to 22 kW AC, Type 2",
