    "chg.f4k": "Energy",
    "chg.f4v": "Paid at the station by QR",
    "trn.h1": "Getting to Zermatt",
    "trn.lead": "How the shuttle train connects Täsch and car-free Zermatt.",
    "trn.p1": "Because Zermatt bans combustion cars, the last leg of the journey is by rail. The shuttle train runs between Täsch and Zermatt from early morning until late at night, roughly every 20 minutes, and covers the distance in about 12 minutes.",
    "trn.h2a": "Tickets & platform",
    "trn.p2": "The platform is right next to the car park — no street to cross, with lifts and ramps down to the tracks. Buy shuttle tickets from the machines in the terminal or in the station app; they are separate from your parking reservation.",
    "trn.callout": "keep your parking confirmation on your phone. It is tied to your licence plate, not to the train ticket, which you buy separately.",
    "trn.h2b": "Luggage & onward travel",
    "trn.p3": "There are baggage trolleys on both platforms, and many Zermatt hotels send an electro-taxi to meet guests at the Zermatt end. Leave a little buffer in high season, when trains and platforms are busy.",
    "trn.f1k": "Line",
    "trn.f1v": "Täsch ⇄ Zermatt shuttle",
    "trn.f2k": "Frequency",
    "trn.f2v": "≈ every 20 min",
