    "trn.f4v": "Bought separately",
    "bus.h1": "Coaches & groups",
    "bus.lead": "Where coaches stop at the terminal and how groups continue to Zermatt.",
    "bus.p1": "Tour coaches use the terminal in Täsch just like cars — Zermatt itself cannot be reached by coach. There are marked coach bays and a drop-off area beside the station where a group can get out before the coach parks.",
    "bus.h2a": "Parking the coach",
    "bus.p2": "Coach parking is arranged at the terminal; for large groups and longer stays it is best to contact the terminal ahead of time so a bay is ready when you arrive. Our online form is designed for cars and electric cars, so it is not used for coaches.",
    "bus.h2b": "Onward to Zermatt",
    "bus.p3": "From the drop-off it is a short walk to the shuttle-train platform. Group rail tickets to Zermatt can be organised in advance; allow extra time to move a full coach of passengers and luggage onto the train.",
