    "car.h1": "Anreise mit dem Auto",
    "car.lead": "Wie Sie zum Matterhorn Terminal in Täsch fahren und wo Sie das Auto für Zermatt abstellen.",
    "car.p1": "Zermatt ist autofrei, daher endet jede Autofahrt zum Matterhorn in Täsch. Aus dem Rhonetal folgen Sie der Kantonsstrasse hinauf über Visp, St. Niklaus und Randa; das Matterhorn Terminal liegt direkt neben dem Bahnhof Täsch am Ende der Talstrasse. Stellen Sie Ihr Navi auf „Matterhorn Terminal Täsch“ und es führt Sie direkt zur Einfahrt.",
    "car.h2a": "Parken am Terminal",
    "car.p2": "Das Terminal ist ein überdachtes Parkhaus mit rund 2.100 Plätzen. Bei der Online-Buchung wird Ihr Kennzeichen gespeichert, sodass sich die Schranke bei der Ankunft automatisch öffnet und Sie direkt zu einem Platz fahren — es gibt kein Papierticket. Buchen Sie „Parken“ für einen normalen Platz oder „Parken mit E-Ladestation“, wenn Ihr Auto laden soll.",
    "car.callout": "buchen Sie online, bevor Sie losfahren. Ihr Kennzeichen wird an der Schranke erkannt, sodass Sie die Kassenautomaten bei Ein- und Ausfahrt umgehen.",
    "car.h2b": "Die Höhenbegrenzung",
    "car.p3": "Die maximale Fahrzeughöhe beträgt 2,30 Meter, was normale Autos, Kombis und die meisten SUVs ohne Dachbox abdeckt. Höhere Fahrzeuge und Wohnmobile können die überdachte Garage nicht nutzen — die Seite Busse & Gruppen zeigt die Alternativen für übergrosse Fahrzeuge.",
    "car.h2c": "Vom Auto nach Zermatt",
    "car.p4": "Der Bahnsteig des Shuttlezugs ist zwei Gehminuten von der Garage entfernt. Züge ins autofreie Zermatt fahren etwa alle 20 Minuten und brauchen rund 12 Minuten; Taxis und Hotel-Elektroshuttles halten ebenfalls am Terminal.",
