    "car.f4v": "Shuttlezug, ≈ 12 Min.",
    "chg.h1": "Elektrofahrzeuge & Laden",
    "chg.lead": "Laden Ihres Elektroautos während des Zermatt-Besuchs und wie Sie einen Ladeplatz reservieren.",
    "chg.p1": "Das Matterhorn Terminal ist einer der grössten Ladestandorte der Alpen mit 131 Ladestationen im überdachten Parkhaus. Die Stationen liefern bis zu 22 kW (AC) mit fest angeschlossenem Kabel und Typ-2-Stecker, sodass die meisten Elektroautos bequem laden, während Sie oben in Zermatt sind.",
    "chg.h2a": "Einen Ladeplatz reservieren",
    "chg.p2": "Wählen Sie bei der Buchung „Parken mit E-Ladestation“ statt normalem Parken. Damit reservieren Sie für Ihren gesamten Aufenthalt einen Platz neben einer Ladesäule und müssen bei der Ankunft nicht nach einer freien Station suchen.",
