    "trn.p1": "Da Zermatt Verbrennerautos verbietet, erfolgt der letzte Teil der Reise mit der Bahn. Der Shuttlezug fährt von früh morgens bis spät abends zwischen Täsch und Zermatt, etwa alle 20 Minuten, und legt die Strecke in rund 12 Minuten zurück.",
    "trn.h2a": "Tickets & Bahnsteig",
    "trn.p2": "Der Bahnsteig liegt direkt neben dem Parkhaus — keine Strasse zu überqueren, mit Aufzügen und Rampen zu den Gleisen. Shuttle-Tickets kaufen Sie an den Automaten im Terminal oder in der Bahn-App; sie sind von Ihrer Parkreservierung getrennt.",
