    "trn.p3": "Auf beiden Bahnsteigen gibt es Gepäckwagen, und viele Zermatter Hotels schicken ein Elektrotaxi, um Gäste am Zermatter Ende abzuholen. Planen Sie in der Hochsaison etwas Puffer ein, wenn Züge und Bahnsteige voll sind.",
    "trn.f1k": "Linie",
    "trn.f1v": "Shuttle Täsch ⇄ Zermatt",
    "trn.f2k": "Takt",
    "trn.f2v": "≈ alle 20 Min.",
    "trn.f3k": "Fahrzeit",
    "trn.f3v": "≈ 12 Min.",
    "trn.f4k": "Tickets",
    "trn.f4v": "Separat gekauft",
    "bus.h1": "Busse & Gruppen",
    "bus.lead": "Wo Busse am Terminal halten und wie Gruppen nach Zermatt weiterreisen.",
    "bus.p1": "Reisebusse nutzen das Terminal in Täsch wie Autos — Zermatt selbst ist mit dem Bus nicht erreichbar. Es gibt markierte Busbuchten und einen Drop-off-Bereich neben dem Bahnhof, wo eine Gruppe aussteigen kann, bevor der Bus parkt.",
    "bus.h2a": "Den Bus parken",
    "bus.p2": "Das Busparken wird am Terminal organisiert; für grosse Gruppen und längere Aufenthalte kontaktieren Sie das Terminal am besten im Voraus, damit bei der Ankunft eine Bucht bereitsteht. Unser Online-Formular ist für Autos und Elektroautos ausgelegt und wird daher nicht für Busse verwendet.",
    "bus.h2b": "Weiter nach Zermatt",
    "bus.p3": "Vom Drop-off sind es nur wenige Schritte zum Bahnsteig des Shuttlezugs. Gruppen-Bahntickets nach Zermatt lassen sich im Voraus organisieren; planen Sie zusätzliche Zeit ein, um einen ganzen Bus voller Fahrgäste und Gepäck in den Zug zu bringen.",
    "bus.f1k": "Busse",
    "bus.f1v": "Buchten am Terminal",
    "bus.f2k": "Buchung",
    "bus.f2v": "Mit dem Terminal abstimmen",
    "bus.f3k": "Drop-off",
    "bus.f3v": "Neben dem Bahnhof",
    "bus.f4k": "Nach Zermatt",
    "bus.f4v": "Mit dem Shuttlezug",
    "red.h1": "Eingeschränkte Mobilität & Barrierefreiheit",
    "red.lead": "Barrierefreies Parken am Terminal und stufenloser Zugang zum Shuttlezug.",
    "red.p1": "Das Matterhorn Terminal ist stufenlos gestaltet. Barrierefreie Parkplätze liegen nahe den Aufzügen, die Sie ohne Treppen direkt zum Bahnsteig des Shuttlezugs bringen.",
    "red.h2a": "Parken nahe den Aufzügen",
    "red.p2": "Reservieren Sie online wie gewohnt einen normalen Platz; wenn Sie einen Behindertenparkausweis besitzen, parken Sie bei der Ankunft in einer markierten barrierefreien Bucht nahe dem Aufzugskern. Dank Kennzeichenschranke gibt es keinen Automaten, den Sie vom Auto aus erreichen müssen.",
    "red.h2b": "In den Zug und nach Zermatt",
    "red.p3": "Aufzüge und Rampen verbinden das Parkhaus mit dem Bahnsteig, und die Shuttlezüge nehmen Rollstühle mit. In Zermatt können Elektrotaxis für die Weiterfahrt zum Hotel gebucht werden. Bringen Sie mit, was Sie für einen reibungslosen Transfer brauchen:",
    "red.li1": "Ihre Parkbestätigung (an Ihr Kennzeichen gebunden)",
    "red.li2": "Einen gültigen Behindertenparkausweis für die barrierefreien Buchten",
    "red.f1k": "Zugang",
    "red.f1v": "Stufenlos, Aufzüge zum Bahnsteig",
