    "msg.navDemo": "Questa è solo una demo della schermata di prenotazione.",
    "hero.title": "Prenota il tuo parcheggio<br>a Täsch per Zermatt",
    "hero.subtitle": "Prenota il tuo posto al Matterhorn Terminal di Täsch e raggiungi Zermatt senza auto con il treno navetta.",
    "info.title": "Parcheggia e raggiungi Zermatt",
    "info.guarantee": "Zermatt è senza auto. Lascia l'auto al Matterhorn Terminal di Täsch e prendi il treno navetta — parte circa ogni 20 minuti e raggiunge Zermatt in circa 12 minuti.",
    "info.process": "Prenoti online in pochi clic. Dopo il pagamento ricevi un'e-mail di conferma con la tua prenotazione. La tua targa viene registrata per la barriera, così grazie al riconoscimento targa entri direttamente nel parcheggio coperto all'arrivo — nessun biglietto da smarrire.",
    "info.extra": "Il terminal dispone di circa 2.100 posti coperti e 131 stazioni di ricarica. Scegli «Parcheggio con stazione di ricarica» al momento della prenotazione per riservare una piazzola di ricarica per la tua auto elettrica.",
    "adv.title": "Vantaggi",
