    "msg.navDemo": "Esta es solo una demostración de la pantalla de reserva.",
    "hero.title": "Reserva tu parking<br>en Täsch para Zermatt",
    "hero.subtitle": "Reserva tu plaza en el Matterhorn Terminal de Täsch y llega a Zermatt sin coches en el tren lanzadera.",
    "info.title": "Aparca y llega a Zermatt",
    "info.guarantee": "Zermatt es libre de coches. Deja tu coche en el Matterhorn Terminal de Täsch y toma el tren lanzadera — sale aproximadamente cada 20 minutos y llega a Zermatt en unos 12 minutos.",
    "info.process": "Reserva en línea en unos pocos clics. Tras el pago recibes un correo de confirmación con tu reserva. Tu matrícula queda registrada para la barrera, así que gracias al reconocimiento de matrícula entras directamente en el aparcamiento cubierto al llegar — sin ticket que perder.",
    "info.extra": "El terminal cuenta con unas 2.100 plazas cubiertas y 131 estaciones de recarga. Elige «Parking con estación de recarga» al reservar para reservar una plaza de recarga para tu coche eléctrico.",
    "adv.title": "Ventajas",
