    "hero.title": "Foglaljon parkolást<br>Täschben Zermatthoz",
    "hero.subtitle": "Foglaljon helyet a täschi Matterhorn Terminalban, és utazzon az autómentes Zermattba az ingavonattal.",
    "info.title": "Parkoljon, és utazzon tovább Zermattba",
    "info.guarantee": "Zermatt autómentes. Hagyja autóját a täschi Matterhorn Terminalban, és szálljon fel az ingavonatra — nagyjából 20 percenként indul, és körülbelül 12 perc alatt ér Zermattba.",
    "info.process": "Foglaljon online néhány kattintással. A fizetés után visszaigazoló e-mailt kap a foglalásáról. A rendszáma rögzül a sorompóhoz, így a rendszámfelismerésnek köszönhetően érkezéskor egyenesen a fedett parkolóházba hajthat be — nincs elveszíthető jegy.",
    "info.extra": "A terminál mintegy 2100 fedett hellyel és 131 töltőállomással rendelkezik. Foglaláskor válassza a „Parkolás töltőállomással” lehetőséget, hogy töltőhelyet foglaljon elektromos autójának.",
