    "info.title": "Parchează și continuă spre Zermatt",
    "info.guarantee": "Zermatt este fără mașini. Lasă mașina la Matterhorn Terminal din Täsch și ia trenul navetă — circulă cam la fiecare 20 de minute și ajunge în Zermatt în aproximativ 12 minute.",
    "info.process": "Rezervi online în câteva clicuri. După plată primești un e-mail de confirmare cu rezervarea. Numărul de înmatriculare este înregistrat pentru barieră, astfel încât, datorită recunoașterii plăcuțelor, la sosire intri direct în parcarea acoperită — fără tichet de pierdut.",
