    "msg.navDemo": "Toto je pouze ukázka rezervační obrazovky.",
    "hero.title": "Rezervujte si parkování<br>v Täsch pro Zermatt",
    "hero.subtitle": "Rezervujte si místo v Matterhorn Terminalu v Täsch a přijeďte do bezautomobilového Zermattu kyvadlovým vlakem.",
    "info.title": "Zaparkujte a pokračujte do Zermattu",
    "info.guarantee": "Zermatt je bez aut. Nechte auto v Matterhorn Terminalu v Täsch a nasedněte na kyvadlový vlak — jezdí zhruba každých 20 minut a do Zermattu dojede asi za 12 minut.",
    "info.process": "Rezervujte online na pár kliknutí. Po platbě obdržíte potvrzovací e-mail s rezervací. Vaše registrační značka se uloží pro závoru, takže díky rozpoznávání značek při příjezdu vjedete rovnou do krytého parkovacího domu — žádný lístek, který byste mohli ztratit.",
    "info.extra": "Terminal má přibližně 2 100 krytých míst a 131 nabíjecích stanic. Při rezervaci zvolte „Parkování s nabíjecí stanicí“ a rezervujte si nabíjecí místo pro svůj elektromobil.",
    "adv.title": "Výhody",
