    "adv.covered.t": "Krytý parkovací dům",
    "adv.covered.d": "Místo chráněné před počasím ve vícepatrovém terminalu, ať už se v horách děje cokoli.",
    "adv.plate.t": "Rozpoznávání značek",
    "adv.plate.d": "Vaše značka otevře závoru automaticky — vjedete rovnou, bez lístku.",
