    "adv.charge.t": "Nabíjení na místě",
    "adv.charge.d": "131 nabíjecích stanic pro elektromobily — rezervujte si nabíjecí místo spolu se svým parkovacím místem.",
    "weather.title": "Počasí v Zermattu",
