    "info.title": "Parkeer & reis door naar Zermatt",
    "info.guarantee": "Zermatt is autovrij. Laat je auto achter bij de Matterhorn Terminal in Täsch en neem de pendeltrein — hij rijdt ongeveer elke 20 minuten en bereikt Zermatt in zo'n 12 minuten.",
    "info.process": "Boek online in een paar klikken. Na betaling ontvang je een bevestigingsmail met je reservering. Je kenteken wordt geregistreerd voor de slagboom, zodat je dankzij kentekenherkenning bij aankomst direct de overdekte garage in rijdt — geen ticket om te verliezen.",
    "info.extra": "De terminal heeft ongeveer 2.100 overdekte plaatsen en 131 laadstations. Kies bij het boeken «Parkeren met laadstation» om een laadplek voor je elektrische auto te reserveren.",
