    "book.dob": "Geboortedatum",
    "gh.title": "Parkeerinfo",
    "gh.lead": "Alles wat je moet weten om te parkeren bij de Matterhorn Terminal in Täsch en het autovrije Zermatt te bereiken — hoe je er komt, je elektrische auto opladen en hoe de pendeltrein werkt.",
    "gh.banner": "Zermatt is autovrij. Elke auto stopt in Täsch: parkeer bij de Matterhorn Terminal en reis verder met de pendeltrein of taxi.",
    "gh.car.d": "Rijd via de dalweg naar Täsch, parkeer in de overdekte terminal en stap op de trein. Route en hoogtebeperking.",
    "gh.charging.d": "131 laadstations bij de terminal. Reserveer een laadplek bij je plaats en laad op terwijl je in Zermatt bent.",
    "gh.train.d": "De pendeltrein verbindt Täsch en Zermatt in ongeveer 12 minuten, ongeveer elke 20 minuten. Tickets, dienstregeling en bagage.",
    "gh.bus.d": "Busplaatsen en een uitstapzone bij de terminal, plus hoe groepen doorreizen naar Zermatt. Wat je vooraf regelt.",
    "gh.reduced.d": "Toegankelijke plaatsen dicht bij de liften en drempelvrije toegang tot het perron van de pendeltrein.",
    "car.h1": "Aankomst met de auto",
    "car.lead": "Hoe je naar de Matterhorn Terminal in Täsch rijdt en waar je de auto laat voor Zermatt.",
    "car.p1": "Zermatt is autovrij, dus elke autorit naar de Matterhorn eindigt in Täsch. Vanuit het Rhônedal volg je de kantonnale weg omhoog via Visp, St. Niklaus en Randa; de Matterhorn Terminal ligt pal naast station Täsch, aan het einde van de dalweg. Stel je navigatie in op «Matterhorn Terminal Täsch» en die brengt je rechtstreeks naar de ingang.",
    "car.h2a": "Parkeren bij de terminal",
    "car.p2": "De terminal is een overdekte parkeergarage met meerdere lagen en ongeveer 2.100 plaatsen. Bij het online boeken wordt je kenteken opgeslagen, zodat de slagboom bij aankomst automatisch opent en je direct naar een plek rijdt — geen papieren ticket om te bewaren. Kies «Parkeren» voor een gewone plek, of «Parkeren met laadstation» als je auto moet laden.",
    "car.callout": "boek online voordat je vertrekt. Je kenteken wordt bij de slagboom herkend, zodat je de betaalautomaten bij in- en uitrit overslaat.",
    "car.h2b": "De hoogtebeperking",
    "car.p3": "De maximale voertuighoogte is 2,30 meter, wat gewone auto's, stationwagens en de meeste SUV's dekt zodra een dakkoffer is verwijderd. Hogere voertuigen en campers kunnen de overdekte garage niet gebruiken — de pagina bussen & groepen toont de alternatieven voor grote voertuigen.",
    "car.h2c": "Van de auto naar Zermatt",
    "car.p4": "Het perron van de pendeltrein ligt op twee minuten lopen van de garage. Treinen naar het autovrije Zermatt rijden ongeveer elke 20 minuten en duren ongeveer 12 minuten; taxi's en elektrische hotelshuttles pikken ook op bij de terminal.",
    "car.f1k": "Parkeergarage",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Plaatsen",
    "car.f2v": "≈ 2.100, overdekt",
    "car.f3k": "Max. hoogte",
    "car.f3v": "2,30 m",
    "car.f4k": "Naar Zermatt",
    "car.f4v": "Pendeltrein, ≈ 12 min",
    "chg.h1": "Elektrische voertuigen & laden",
    "chg.lead": "Je elektrische auto opladen tijdens je bezoek aan Zermatt en hoe je een laadplek reserveert.",
    "chg.p1": "De Matterhorn Terminal is een van de grootste laadlocaties in de Alpen, met 131 laadstations ingebouwd in de overdekte parkeergarage. De stations leveren tot 22 kW (AC) met een vaste kabel en Type 2-stekker, zodat de meeste elektrische auto's comfortabel laden terwijl jij boven in Zermatt bent.",
    "chg.h2a": "Een laadplek reserveren",
    "chg.p2": "Kies bij het boeken «Parkeren met laadstation» in plaats van gewoon parkeren. Zo reserveer je voor je hele verblijf een plek naast een lader en hoef je bij aankomst niet naar een vrije unit te zoeken.",
    "chg.callout": "kies «Parkeren met laadstation» in de eerste stap van het boekingsformulier om een lader voor je data te garanderen.",
    "chg.h2b": "De energie betalen",
    "chg.p3": "Je reservering dekt de parkeerplaats en de laadplek. De energie die je daadwerkelijk afneemt, wordt apart bij het station afgerekend via QR-code — creditcard, TWINT, Apple Pay en Google Pay worden geaccepteerd — zo betaal je alleen de stroom die je gebruikt.",
    "chg.f1k": "Stations",
    "chg.f1v": "131, in de garage",
    "chg.f2k": "Vermogen",
    "chg.f2v": "tot 22 kW AC, Type 2",
    "chg.f3k": "Reserveren",
    "chg.f3v": "«Parkeren met laadstation»",
    "chg.f4k": "Energie",
    "chg.f4v": "Betaald bij het station via QR",
    "trn.h1": "Naar Zermatt reizen",
    "trn.lead": "Hoe de pendeltrein Täsch en het autovrije Zermatt verbindt.",
    "trn.p1": "Omdat Zermatt auto's met verbrandingsmotor verbiedt, gaat het laatste deel van de reis per trein. De pendeltrein rijdt tussen Täsch en Zermatt van 's ochtends vroeg tot laat in de avond, ongeveer elke 20 minuten, en legt de afstand af in zo'n 12 minuten.",
    "trn.h2a": "Tickets & perron",
    "trn.p2": "Het perron ligt pal naast de parkeergarage — geen straat om over te steken, met liften en hellingbanen naar de sporen. Koop pendeltickets bij de automaten in de terminal of in de spoor-app; ze staan los van je parkeerreservering.",
    "trn.callout": "houd je parkeerbevestiging op je telefoon. Die is gekoppeld aan je kenteken, niet aan het treinticket, dat je apart koopt.",
    "trn.h2b": "Bagage & doorreis",
    "trn.p3": "Op beide perrons staan bagagekarren, en veel hotels in Zermatt sturen een elektrische taxi om gasten aan de Zermatt-kant op te halen. Houd wat marge aan in het hoogseizoen, wanneer treinen en perrons druk zijn.",
    "trn.f1k": "Lijn",
    "trn.f1v": "Pendel Täsch ⇄ Zermatt",
    "trn.f2k": "Frequentie",
    "trn.f2v": "≈ elke 20 min",
    "trn.f3k": "Reistijd",
    "trn.f3v": "≈ 12 min",
    "trn.f4k": "Tickets",
    "trn.f4v": "Apart gekocht",
    "bus.h1": "Bussen & groepen",
    "bus.lead": "Waar bussen stoppen bij de terminal en hoe groepen doorreizen naar Zermatt.",
    "bus.p1": "Touringcars gebruiken de terminal in Täsch net als auto's — Zermatt zelf is niet per bus bereikbaar. Er zijn gemarkeerde busplaatsen en een uitstapzone naast het station, waar een groep kan uitstappen voordat de bus parkeert.",
    "bus.h2a": "De bus parkeren",
    "bus.p2": "Busparkeren wordt bij de terminal geregeld; voor grote groepen en langere verblijven kun je het beste vooraf contact opnemen met de terminal, zodat er bij aankomst een plek klaarstaat. Ons online formulier is bedoeld voor auto's en elektrische auto's en wordt dus niet voor bussen gebruikt.",
    "bus.h2b": "Verder naar Zermatt",
    "bus.p3": "Vanaf de uitstapzone is het perron van de pendeltrein een klein stukje lopen. Groepstreintickets naar Zermatt kunnen vooraf worden geregeld; reken extra tijd om een volle bus met passagiers en bagage in de trein te krijgen.",
    "bus.f1k": "Bussen",
    "bus.f1v": "Plaatsen bij de terminal",
    "bus.f2k": "Reservering",
    "bus.f2v": "Afstemmen met de terminal",
    "bus.f3k": "Uitstappen",
    "bus.f3v": "Naast het station",
    "bus.f4k": "Naar Zermatt",
    "bus.f4v": "Met de pendeltrein",
    "red.h1": "Beperkte mobiliteit & toegankelijkheid",
    "red.lead": "Toegankelijk parkeren bij de terminal en drempelvrije toegang tot de pendeltrein.",
    "red.p1": "De Matterhorn Terminal is drempelvrij ontworpen. Toegankelijke parkeerplaatsen liggen dicht bij de liften, die je zonder trappen rechtstreeks naar het perron van de pendeltrein brengen.",
    "red.h2a": "Parkeren dicht bij de liften",
    "red.p2": "Reserveer online op de gebruikelijke manier een gewone plek; heb je een gehandicaptenparkeerkaart, parkeer dan bij aankomst op een gemarkeerde toegankelijke plek bij de liftkern. Dankzij de kentekenslagboom hoef je vanuit de auto geen automaat te bereiken.",
    "red.h2b": "De trein in en naar Zermatt",
    "red.p3": "Liften en hellingbanen verbinden de parkeergarage met het perron, en de pendeltreinen nemen rolstoelen mee. In Zermatt zijn elektrische taxi's te boeken om door te reizen naar je hotel. Neem mee wat je nodig hebt voor een soepele overstap:",
    "red.li1": "Je parkeerbevestiging (gekoppeld aan je kenteken)",
    "red.li2": "Een geldige gehandicaptenparkeerkaart voor de toegankelijke plekken",
