    "gh.car.d": "Pripeljite se v Täsch po dolinski cesti, parkirajte v pokritem terminalu in se vkrcajte na vlak. Pot in omejitev višine.",
    "gh.charging.d": "131 polnilnih postaj na terminalu. Rezervirajte polnilno mesto skupaj z mestom in polnite, medtem ko ste v Zermattu.",
    "gh.train.d": "Vlak povezuje Täsch in Zermatt v približno 12 minutah, približno vsakih 20 minut. Vozovnice, vozni red in prtljaga.",
    "gh.bus.d": "Mesta za avtobuse in mesto za izstop na terminalu ter kako skupine nadaljujejo v Zermatt. Kaj urediti vnaprej.",
