    "car.h1": "Prihod z avtomobilom",
    "car.lead": "Kako se pripeljati do Matterhorn Terminala v Täschu in kje pustiti avto za Zermatt.",
    "car.p1": "Zermatt je brez avtomobilov, zato se vsaka vožnja k Matterhornu konča v Täschu. Iz doline Rone nadaljujete po kantonski cesti navzgor skozi Visp, St. Niklaus in Rando; Matterhorn Terminal stoji tik ob postaji Täsch na koncu dolinske ceste. Navigacijo nastavite na »Matterhorn Terminal Täsch« in vas popelje naravnost do vhoda.",
    "car.h2a": "Parkiranje na terminalu",
    "car.p2": "Terminal je pokrita večnadstropna garaža z približno 2.100 mesti. Ob spletni rezervaciji se shrani vaša tablica, tako da se zapornica ob prihodu samodejno odpre in se odpeljete naravnost do mesta — brez papirnatega listka za shranjevanje. Izberite »Parkiranje« za običajno mesto ali »Parkiranje s polnilno postajo«, če se mora avto polniti.",
    "car.callout": "rezervirajte na spletu, preden se odpravite. Vaša tablica se prepozna pri zapornici, tako da se ob vhodu in izhodu izognete plačilnim avtomatom.",
    "car.h2b": "Omejitev višine",
    "car.p3": "Največja višina vozil je 2,30 metra, kar zajema običajne avtomobile, karavane in večino terencev, ko odstranite strešni kovček. Višja vozila in avtodomi ne morejo uporabljati pokrite garaže — stran avtobusi in skupine navaja rešitve za nadmerna vozila.",
    "car.h2c": "Od avta do Zermatta",
    "car.p4": "Peron vlaka je dve minuti hoje od garaže. Vlaki v Zermatt brez avtomobilov vozijo približno vsakih 20 minut in trajajo približno 12 minut; taksiji in električni hotelski prevozi prav tako pobirajo potnike na terminalu.",
    "car.f1k": "Parkirišče",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Mesta",
    "car.f2v": "≈ 2.100, pokrita",
    "car.f3k": "Najv. višina",
    "car.f3v": "2,30 m",
    "car.f4k": "V Zermatt",
    "car.f4v": "Vlak, ≈ 12 min",
    "chg.h1": "Električna vozila in polnjenje",
    "chg.lead": "Polnjenje električnega avta med obiskom Zermatta in kako rezervirati polnilno mesto.",
    "chg.p1": "Matterhorn Terminal je eno največjih polnilnih mest v Alpah s 131 postajami, vgrajenimi v pokrito garažo. Postaje zagotavljajo do 22 kW (AC) s pritrjenim kablom in vtičem Type 2, tako da se večina električnih avtomobilov udobno napolni, medtem ko ste zgoraj v Zermattu.",
    "chg.h2a": "Rezervacija polnilnega mesta",
    "chg.p2": "Ob rezervaciji izberite »Parkiranje s polnilno postajo« namesto običajnega parkiranja. S tem za celoten čas bivanja rezervirate mesto ob polnilnici in vam ob prihodu ni treba iskati proste enote.",
    "chg.callout": "izberite »Parkiranje s polnilno postajo« v prvem koraku obrazca za rezervacijo in si zagotovite polnilnico za svoje datume.",
    "chg.h2b": "Plačilo energije",
    "chg.p3": "Vaša rezervacija zajema parkirno in polnilno mesto. Dejansko porabljena energija se obračuna posebej pri postaji prek kode QR — sprejeti so kreditna kartica, TWINT, Apple Pay in Google Pay — tako plačate le elektriko, ki jo porabite.",
    "chg.f1k": "Postaje",
    "chg.f1v": "131, v garaži",
    "chg.f2k": "Moč",
    "chg.f2v": "do 22 kW AC, Type 2",
    "chg.f3k": "Rezervacija",
    "chg.f3v": "»Parkiranje s polnilno postajo«",
    "chg.f4k": "Energija",
    "chg.f4v": "Plačana pri postaji prek QR",
    "trn.h1": "Pot v Zermatt",
    "trn.lead": "Kako vlak povezuje Täsch in Zermatt brez avtomobilov.",
    "trn.p1": "Ker Zermatt prepoveduje avtomobile na notranje izgorevanje, zadnji del poti poteka z vlakom. Vlak vozi med Täschem in Zermattom od zgodnjega jutra do poznega večera, približno vsakih 20 minut, razdaljo pa premaga v približno 12 minutah.",
    "trn.h2a": "Vozovnice in peron",
    "trn.p2": "Peron je tik ob garaži — brez prečkanja ceste, z dvigali in klančinami do tirov. Vozovnice za vlak kupite na avtomatih v terminalu ali v aplikaciji železnice; ločene so od rezervacije parkiranja.",
    "trn.callout": "potrdilo o parkiranju imejte v telefonu. Vezano je na vašo tablico, ne na vlakovno vozovnico, ki jo kupite posebej.",
    "trn.h2b": "Prtljaga in nadaljevanje poti",
    "trn.p3": "Na obeh peronih so vozički za prtljago, mnogi hoteli v Zermattu pa pošljejo električni taksi, ki goste pričaka na strani Zermatta. V glavni sezoni si pustite nekaj rezerve, ko so vlaki in peroni polni.",
    "trn.f1k": "Proga",
    "trn.f1v": "Vlak Täsch ⇄ Zermatt",
    "trn.f2k": "Pogostost",
    "trn.f2v": "≈ vsakih 20 min",
    "trn.f3k": "Vožnja",
    "trn.f3v": "≈ 12 min",
    "trn.f4k": "Vozovnice",
    "trn.f4v": "Kupljene posebej",
    "bus.h1": "Avtobusi in skupine",
    "bus.lead": "Kje se avtobusi ustavijo na terminalu in kako skupine nadaljujejo v Zermatt.",
    "bus.p1": "Turistični avtobusi uporabljajo terminal v Täschu tako kot avtomobili — v sam Zermatt z avtobusom ni mogoče. Ob postaji so označena mesta za avtobuse in prostor za izstop, kjer lahko skupina izstopi, preden avtobus parkira.",
    "bus.h2a": "Parkiranje avtobusa",
    "bus.p2": "Parkiranje avtobusov se uredi na terminalu; za večje skupine in daljša bivanja je najbolje terminal kontaktirati vnaprej, da je mesto ob prihodu pripravljeno. Naš spletni obrazec je namenjen avtomobilom in električnim avtomobilom, zato se za avtobuse ne uporablja.",
    "bus.h2b": "Naprej v Zermatt",
    "bus.p3": "Od mesta za izstop je peron vlaka le nekaj korakov stran. Skupinske vlakovne vozovnice za Zermatt je mogoče urediti vnaprej; predvidite dodaten čas za prestop celega avtobusa potnikov in prtljage na vlak.",
    "bus.f1k": "Avtobusi",
    "bus.f1v": "Mesta na terminalu",
    "bus.f2k": "Rezervacija",
    "bus.f2v": "Dogovor s terminalom",
    "bus.f3k": "Izstop",
    "bus.f3v": "Ob postaji",
    "bus.f4k": "V Zermatt",
    "bus.f4v": "Z vlakom",
    "red.h1": "Zmanjšana mobilnost in dostopnost",
    "red.lead": "Dostopno parkiranje na terminalu in dostop brez stopnic do vlaka.",
    "red.p1": "Matterhorn Terminal je zasnovan brez stopnic. Dostopna parkirna mesta so blizu dvigal, ki vas brez stopnic pripeljejo naravnost do perona vlaka.",
    "red.h2a": "Parkiranje blizu dvigal",
    "red.p2": "Rezervirajte običajno mesto na spletu na običajen način; če imate parkirno karto za invalide, ob prihodu parkirajte na označenem dostopnem mestu ob jedru dvigal. Zaradi zapornice s prepoznavanjem tablic iz avta ni treba doseči nobenega avtomata.",
    "red.h2b": "Na vlak in v Zermatt",
    "red.p3": "Dvigala in klančine povezujejo garažo s peronom, vlaki pa sprejmejo invalidske vozičke. V Zermattu je mogoče naročiti električne taksije za nadaljevanje do hotela. Prinesite, kar potrebujete za nemoten prestop:",
    "red.li1": "Potrdilo o parkiranju (vezano na vašo tablico)",
    "red.li2": "Veljavno parkirno karto za invalide za dostopna mesta",
    "red.f1k": "Dostop",
    "red.f1v": "Brez stopnic, dvigala do perona",
    "red.f2k": "Mesta",
    "red.f2v": "Dostopna mesta ob dvigalih",
    "red.f3k": "Vlak",
    "red.f3v": "Vlak, dostopen za vozičke",
    "red.f4k": "Prinesite",
    "red.f4v": "Potrdilo + karta za invalide",
    "book.cardTitle": "Rezervirajte mesto v Täschu",
    "book.arrivalDate": "Datum prihoda",
    "book.departureDate": "Datum odhoda"
