    "msg.navDemo": "Esta é apenas uma demonstração do ecrã de reserva.",
    "hero.title": "Reserve o seu estacionamento<br>em Täsch para Zermatt",
    "hero.subtitle": "Reserve o seu lugar no Matterhorn Terminal em Täsch e siga para Zermatt sem carros no comboio de ligação.",
    "info.title": "Estacione e siga para Zermatt",
    "info.guarantee": "Zermatt é livre de carros. Deixe o seu carro no Matterhorn Terminal em Täsch e apanhe o comboio de ligação — parte cerca de cada 20 minutos e chega a Zermatt em cerca de 12 minutos.",
    "info.process": "Reserve online em poucos cliques. Após o pagamento recebe um e-mail de confirmação com a sua reserva. A sua matrícula fica registada para a barreira, por isso, graças ao reconhecimento de matrícula, entra diretamente no parque coberto à chegada — sem bilhete que se possa perder.",
    "info.extra": "O terminal tem cerca de 2.100 lugares cobertos e 131 estações de carregamento. Escolha «Estacionamento com estação de carregamento» ao reservar para reservar um lugar de carregamento para o seu carro elétrico.",
    "adv.title": "Vantagens",
