    "info.title": "Parkirajte i nastavite u Zermatt",
    "info.guarantee": "Zermatt je bez automobila. Ostavite auto na Matterhorn Terminalu u Täschu i sjednite na vlak — polazi otprilike svakih 20 minuta i do Zermatta stiže za oko 12 minuta.",
    "info.process": "Rezervirajte online u nekoliko klikova. Nakon plaćanja primate e-poštu s potvrdom rezervacije. Vaša registarska pločica sprema se za rampu, pa zahvaljujući prepoznavanju pločica pri dolasku ulazite ravno u natkrivenu garažu — bez karte koju biste mogli izgubiti.",
