    "book.dob": "Datum rođenja",
    "gh.title": "Informacije o parkingu",
    "gh.lead": "Sve što trebate znati o parkiranju na Matterhorn Terminalu u Täschu i dolasku u Zermatt bez automobila — kako doći, kako napuniti električni automobil i kako radi vlak.",
    "gh.banner": "Zermatt je bez automobila. Svaki automobil staje u Täschu: parkirajte na Matterhorn Terminalu i nastavite vlakom ili taksijem.",
    "gh.car.d": "Dođite u Täsch dolinskom cestom, parkirajte u natkrivenom terminalu i sjednite na vlak. Ruta i ograničenje visine.",
    "gh.charging.d": "131 stanica za punjenje na terminalu. Rezervirajte mjesto za punjenje sa svojim mjestom i punite dok ste u Zermattu.",
    "gh.train.d": "Vlak povezuje Täsch i Zermatt za oko 12 minuta, otprilike svakih 20 minuta. Karte, vozni red i prtljaga.",
    "gh.bus.d": "Mjesta za autobuse i prostor za iskrcaj na terminalu te kako skupine nastavljaju u Zermatt. Što urediti unaprijed.",
    "gh.reduced.d": "Pristupačna mjesta blizu dizala i pristup bez stepenica do perona vlaka.",
    "car.h1": "Dolazak automobilom",
    "car.lead": "Kako doći do Matterhorn Terminala u Täschu i gdje ostaviti auto za Zermatt.",
    "car.p1": "Zermatt je bez automobila, pa svako putovanje autom prema Matterhornu završava u Täschu. Iz doline Rhône nastavljate kantonalnom cestom uzbrdo kroz Visp, St. Niklaus i Rando; Matterhorn Terminal nalazi se odmah uz kolodvor Täsch na kraju dolinske ceste. Postavite navigaciju na »Matterhorn Terminal Täsch« i odvest će vas ravno do ulaza.",
    "car.h2a": "Parkiranje na terminalu",
    "car.p2": "Terminal je natkrivena višeetažna garaža s oko 2.100 mjesta. Pri online rezervaciji sprema se vaša pločica, pa se rampa pri dolasku automatski otvara i idete ravno do mjesta — bez papirnate karte za čuvanje. Odaberite »Parking« za obično mjesto ili »Parking sa stanicom za punjenje« ako se auto treba puniti.",
    "car.callout": "rezervirajte online prije polaska. Vaša se pločica prepoznaje na rampi, pa izbjegavate naplatne automate pri ulazu i izlazu.",
    "car.h2b": "Ograničenje visine",
    "car.p3": "Maksimalna visina vozila je 2,30 metra, što pokriva obične automobile, karavane i većinu SUV-ova nakon skidanja krovne kutije. Viša vozila i kamperi ne mogu koristiti natkrivenu garažu — stranica autobusi i skupine navodi alternative za vozila velikih dimenzija.",
    "car.h2c": "Od auta do Zermatta",
    "car.p4": "Peron vlaka je dvije minute hoda od garaže. Vlakovi za Zermatt bez automobila polaze otprilike svakih 20 minuta i traju oko 12 minuta; taksiji i električni hotelski prijevozi također preuzimaju putnike na terminalu.",
    "car.f1k": "Parkiralište",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Mjesta",
    "car.f2v": "≈ 2.100, natkrivena",
    "car.f3k": "Maks. visina",
    "car.f3v": "2,30 m",
    "car.f4k": "Do Zermatta",
    "car.f4v": "Vlak, ≈ 12 min",
    "chg.h1": "Električna vozila i punjenje",
    "chg.lead": "Punjenje električnog automobila tijekom posjeta Zermattu i kako rezervirati mjesto za punjenje.",
    "chg.p1": "Matterhorn Terminal jedno je od najvećih mjesta za punjenje u Alpama, sa 131 stanicom ugrađenom u natkrivenu garažu. Stanice pružaju do 22 kW (AC) s fiksnim kabelom i utikačem Type 2, pa se većina električnih automobila udobno napuni dok ste gore u Zermattu.",
    "chg.h2a": "Rezervacija mjesta za punjenje",
    "chg.p2": "Pri rezervaciji odaberite »Parking sa stanicom za punjenje« umjesto običnog parkinga. Time rezervirate mjesto uz punjač za cijeli boravak i pri dolasku ne morate tražiti slobodnu jedinicu.",
    "chg.callout": "odaberite »Parking sa stanicom za punjenje« u prvom koraku obrasca za rezervaciju kako biste osigurali punjač za svoje datume.",
    "chg.h2b": "Plaćanje energije",
    "chg.p3": "Vaša rezervacija pokriva parkirno mjesto i mjesto za punjenje. Stvarno preuzeta energija naplaćuje se zasebno na stanici putem QR koda — prihvaćaju se kreditna kartica, TWINT, Apple Pay i Google Pay — pa plaćate samo struju koju potrošite.",
    "chg.f1k": "Stanice",
    "chg.f1v": "131, u garaži",
    "chg.f2k": "Snaga",
    "chg.f2v": "do 22 kW AC, Type 2",
    "chg.f3k": "Rezervacija",
    "chg.f3v": "»Parking sa stanicom za punjenje«",
    "chg.f4k": "Energija",
    "chg.f4v": "Plaća se na stanici putem QR-a",
    "trn.h1": "Dolazak u Zermatt",
    "trn.lead": "Kako vlak povezuje Täsch i Zermatt bez automobila.",
    "trn.p1": "Budući da Zermatt zabranjuje automobile s motorima s unutarnjim izgaranjem, posljednja dionica putovanja je vlakom. Vlak vozi između Täscha i Zermatta od ranog jutra do kasne večeri, otprilike svakih 20 minuta, a udaljenost prelazi za oko 12 minuta.",
    "trn.h2a": "Karte i peron",
    "trn.p2": "Peron je odmah uz garažu — bez prelaska ceste, s dizalima i rampama do kolosijeka. Karte za vlak kupite na automatima u terminalu ili u aplikaciji željeznice; odvojene su od rezervacije parkinga.",
    "trn.callout": "držite potvrdu parkinga na telefonu. Vezana je uz vašu pločicu, a ne uz kartu za vlak koju kupujete zasebno.",
    "trn.h2b": "Prtljaga i nastavak putovanja",
    "trn.p3": "Na oba perona postoje kolica za prtljagu, a mnogi hoteli u Zermattu šalju električni taksi koji dočekuje goste na strani Zermatta. U jeku sezone ostavite malo rezerve, kad su vlakovi i peroni puni.",
    "trn.f1k": "Linija",
    "trn.f1v": "Vlak Täsch ⇄ Zermatt",
    "trn.f2k": "Učestalost",
    "trn.f2v": "≈ svakih 20 min",
    "trn.f3k": "Vožnja",
    "trn.f3v": "≈ 12 min",
    "trn.f4k": "Karte",
    "trn.f4v": "Kupuju se zasebno",
    "bus.h1": "Autobusi i skupine",
    "bus.lead": "Gdje autobusi staju na terminalu i kako skupine nastavljaju u Zermatt.",
    "bus.p1": "Turistički autobusi koriste terminal u Täschu jednako kao i automobili — do samog Zermatta autobusom se ne može. Uz kolodvor postoje označena mjesta za autobuse i prostor za iskrcaj gdje skupina može izaći prije nego autobus parkira.",
    "bus.h2a": "Parkiranje autobusa",
    "bus.p2": "Parkiranje autobusa dogovara se na terminalu; za velike skupine i dulje boravke najbolje je kontaktirati terminal unaprijed kako bi mjesto bilo spremno pri dolasku. Naš je online obrazac namijenjen automobilima i električnim automobilima pa se ne koristi za autobuse.",
    "bus.h2b": "Dalje u Zermatt",
    "bus.p3": "Od prostora za iskrcaj peron vlaka je nekoliko koraka. Grupne željezničke karte za Zermatt mogu se urediti unaprijed; predvidite dodatno vrijeme za ukrcaj cijelog autobusa putnika i prtljage u vlak.",
    "bus.f1k": "Autobusi",
    "bus.f1v": "Mjesta na terminalu",
    "bus.f2k": "Rezervacija",
    "bus.f2v": "Dogovoriti s terminalom",
    "bus.f3k": "Iskrcaj",
    "bus.f3v": "Uz kolodvor",
    "bus.f4k": "Do Zermatta",
    "bus.f4v": "Vlakom",
    "red.h1": "Smanjena pokretljivost i pristupačnost",
    "red.lead": "Pristupačno parkiranje na terminalu i pristup bez stepenica do vlaka.",
    "red.p1": "Matterhorn Terminal osmišljen je bez stepenica. Pristupačna parkirna mjesta nalaze se blizu dizala koja vas bez stepenica dovode ravno do perona vlaka.",
    "red.h2a": "Parkiranje blizu dizala",
    "red.p2": "Rezervirajte obično mjesto online na uobičajen način; ako imate parkirnu kartu za osobe s invaliditetom, pri dolasku parkirajte na označenom pristupačnom mjestu uz jezgru dizala. Zahvaljujući rampi s prepoznavanjem pločica nema automata do kojeg biste morali dosegnuti iz auta.",
    "red.h2b": "U vlak i u Zermatt",
    "red.p3": "Dizala i rampe povezuju garažu s peronom, a vlakovi primaju invalidska kolica. U Zermattu se mogu naručiti električni taksiji za nastavak do hotela. Ponesite ono što vam treba za lagan prijelaz:",
    "red.li1": "Potvrdu parkinga (vezanu uz vašu pločicu)",
    "red.li2": "Važeću parkirnu kartu za osobe s invaliditetom za pristupačna mjesta",
    "red.f1k": "Pristup",
    "red.f1v": "Bez stepenica, dizala do perona",
    "red.f2k": "Mjesta",
    "red.f2v": "Pristupačna mjesta uz dizala",
    "red.f3k": "Vlak",
    "red.f3v": "Vlak pristupačan za kolica",
    "red.f4k": "Ponesite",
    "red.f4v": "Potvrda + parkirna karta za invalide",
    "book.cardTitle": "Rezervirajte mjesto u Täschu",
    "book.arrivalDate": "Datum dolaska",
    "book.departureDate": "Datum odlaska"
