    "book.dob": "Datum rođenja",
    "gh.title": "Informacije o parkingu",
    "gh.lead": "Sve što treba da znate o parkiranju na Matterhorn Terminalu u Täschu i dolasku u Zermatt bez automobila — kako doći, kako napuniti električni automobil i kako radi voz.",
    "gh.banner": "Zermatt je bez automobila. Svaki automobil staje u Täschu: parkirajte na Matterhorn Terminalu i nastavite vozom ili taksijem.",
    "gh.car.d": "Dođite u Täsch dolinskim putem, parkirajte u natkrivenom terminalu i sednite na voz. Ruta i ograničenje visine.",
    "gh.charging.d": "131 stanica za punjenje na terminalu. Rezervišite mesto za punjenje sa svojim mestom i punite dok ste u Zermattu.",
    "gh.train.d": "Voz povezuje Täsch i Zermatt za oko 12 minuta, otprilike svakih 20 minuta. Karte, red vožnje i prtljag.",
    "gh.bus.d": "Mesta za autobuse i prostor za iskrcavanje na terminalu i kako grupe nastavljaju u Zermatt. Šta urediti unapred.",
    "gh.reduced.d": "Pristupačna mesta blizu liftova i pristup bez stepenika do perona voza.",
    "car.h1": "Dolazak automobilom",
    "car.lead": "Kako doći do Matterhorn Terminala u Täschu i gde ostaviti auto za Zermatt.",
    "car.p1": "Zermatt je bez automobila, pa se svako putovanje autom ka Matterhornu završava u Täschu. Iz doline Rone nastavljate kantonalnim putem uzbrdo kroz Visp, St. Niklaus i Rando; Matterhorn Terminal se nalazi odmah uz stanicu Täsch na kraju dolinskog puta. Postavite navigaciju na »Matterhorn Terminal Täsch« i odvešće vas pravo do ulaza.",
    "car.h2a": "Parkiranje na terminalu",
    "car.p2": "Terminal je natkrivena višespratna garaža sa oko 2.100 mesta. Pri onlajn rezervaciji čuva se vaša tablica, pa se rampa pri dolasku automatski otvara i idete pravo do mesta — bez papirne karte za čuvanje. Izaberite »Parking« za obično mesto ili »Parking sa stanicom za punjenje« ako auto treba da se puni.",
    "car.callout": "rezervišite onlajn pre polaska. Vaša tablica se prepoznaje na rampi, pa izbegavate naplatne automate pri ulazu i izlazu.",
    "car.h2b": "Ograničenje visine",
    "car.p3": "Maksimalna visina vozila je 2,30 metra, što pokriva obične automobile, karavane i većinu SUV vozila nakon skidanja krovnog kofera. Viša vozila i kamperi ne mogu da koriste natkrivenu garažu — stranica autobusi i grupe navodi alternative za vozila velikih dimenzija.",
    "car.h2c": "Od auta do Zermatta",
    "car.p4": "Peron voza je dva minuta hoda od garaže. Vozovi za Zermatt bez automobila polaze otprilike svakih 20 minuta i traju oko 12 minuta; taksiji i električni hotelski prevozi takođe preuzimaju putnike na terminalu.",
    "car.f1k": "Parking",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Mesta",
    "car.f2v": "≈ 2.100, natkrivena",
    "car.f3k": "Maks. visina",
    "car.f3v": "2,30 m",
    "car.f4k": "Do Zermatta",
    "car.f4v": "Voz, ≈ 12 min",
    "chg.h1": "Električna vozila i punjenje",
    "chg.lead": "Punjenje električnog automobila tokom posete Zermattu i kako rezervisati mesto za punjenje.",
    "chg.p1": "Matterhorn Terminal je jedno od najvećih mesta za punjenje u Alpima, sa 131 stanicom ugrađenom u natkrivenu garažu. Stanice pružaju do 22 kW (AC) sa fiksnim kablom i utikačem Type 2, pa se većina električnih automobila udobno napuni dok ste gore u Zermattu.",
    "chg.h2a": "Rezervacija mesta za punjenje",
    "chg.p2": "Pri rezervaciji izaberite »Parking sa stanicom za punjenje« umesto običnog parkinga. Time rezervišete mesto pored punjača za ceo boravak i pri dolasku ne morate da tražite slobodnu jedinicu.",
    "chg.callout": "izaberite »Parking sa stanicom za punjenje« u prvom koraku obrasca za rezervaciju da biste osigurali punjač za svoje datume.",
    "chg.h2b": "Plaćanje energije",
    "chg.p3": "Vaša rezervacija pokriva parking mesto i mesto za punjenje. Stvarno preuzeta energija naplaćuje se posebno na stanici putem QR koda — prihvataju se kreditna kartica, TWINT, Apple Pay i Google Pay — pa plaćate samo struju koju potrošite.",
    "chg.f1k": "Stanice",
    "chg.f1v": "131, u garaži",
    "chg.f2k": "Snaga",
    "chg.f2v": "do 22 kW AC, Type 2",
    "chg.f3k": "Rezervacija",
    "chg.f3v": "»Parking sa stanicom za punjenje«",
    "chg.f4k": "Energija",
    "chg.f4v": "Plaća se na stanici putem QR-a",
    "trn.h1": "Dolazak u Zermatt",
    "trn.lead": "Kako voz povezuje Täsch i Zermatt bez automobila.",
    "trn.p1": "Pošto Zermatt zabranjuje automobile sa motorima sa unutrašnjim sagorevanjem, poslednja deonica putovanja je vozom. Voz saobraća između Täscha i Zermatta od ranog jutra do kasne večeri, otprilike svakih 20 minuta, a rastojanje prelazi za oko 12 minuta.",
    "trn.h2a": "Karte i peron",
    "trn.p2": "Peron je odmah uz garažu — bez prelaska ulice, sa liftovima i rampama do koloseka. Karte za voz kupite na automatima u terminalu ili u aplikaciji železnice; odvojene su od rezervacije parkinga.",
    "trn.callout": "držite potvrdu parkinga na telefonu. Vezana je za vašu tablicu, a ne za voznu kartu koju kupujete posebno.",
    "trn.h2b": "Prtljag i nastavak putovanja",
    "trn.p3": "Na oba perona postoje kolica za prtljag, a mnogi hoteli u Zermattu šalju električni taksi koji dočekuje goste na strani Zermatta. U jeku sezone ostavite malo rezerve, kad su vozovi i peroni puni.",
    "trn.f1k": "Linija",
    "trn.f1v": "Voz Täsch ⇄ Zermatt",
    "trn.f2k": "Učestalost",
    "trn.f2v": "≈ svakih 20 min",
    "trn.f3k": "Vožnja",
    "trn.f3v": "≈ 12 min",
    "trn.f4k": "Karte",
    "trn.f4v": "Kupuju se posebno",
    "bus.h1": "Autobusi i grupe",
    "bus.lead": "Gde autobusi staju na terminalu i kako grupe nastavljaju u Zermatt.",
    "bus.p1": "Turistički autobusi koriste terminal u Täschu isto kao i automobili — do samog Zermatta autobusom se ne može. Uz stanicu postoje označena mesta za autobuse i prostor za iskrcavanje gde grupa može da izađe pre nego što autobus parkira.",
    "bus.h2a": "Parkiranje autobusa",
    "bus.p2": "Parkiranje autobusa dogovara se na terminalu; za velike grupe i duže boravke najbolje je kontaktirati terminal unapred kako bi mesto bilo spremno pri dolasku. Naš onlajn obrazac namenjen je automobilima i električnim automobilima pa se ne koristi za autobuse.",
    "bus.h2b": "Dalje u Zermatt",
    "bus.p3": "Od prostora za iskrcavanje peron voza je nekoliko koraka. Grupne železničke karte za Zermatt mogu se urediti unapred; predvidite dodatno vreme za ukrcavanje celog autobusa putnika i prtljaga u voz.",
    "bus.f1k": "Autobusi",
    "bus.f1v": "Mesta na terminalu",
    "bus.f2k": "Rezervacija",
    "bus.f2v": "Dogovoriti sa terminalom",
    "bus.f3k": "Iskrcavanje",
    "bus.f3v": "Uz stanicu",
    "bus.f4k": "Do Zermatta",
    "bus.f4v": "Vozom",
    "red.h1": "Smanjena pokretljivost i pristupačnost",
    "red.lead": "Pristupačno parkiranje na terminalu i pristup bez stepenika do voza.",
    "red.p1": "Matterhorn Terminal je osmišljen bez stepenika. Pristupačna parking mesta nalaze se blizu liftova koji vas bez stepenika dovode pravo do perona voza.",
    "red.h2a": "Parkiranje blizu liftova",
    "red.p2": "Rezervišite obično mesto onlajn na uobičajen način; ako imate parking kartu za osobe sa invaliditetom, pri dolasku parkirajte na označenom pristupačnom mestu uz jezgro liftova. Zahvaljujući rampi sa prepoznavanjem tablica nema automata do kojeg biste morali da dosegnete iz auta.",
    "red.h2b": "U voz i u Zermatt",
    "red.p3": "Liftovi i rampe povezuju garažu sa peronom, a vozovi primaju invalidska kolica. U Zermattu se mogu naručiti električni taksiji za nastavak do hotela. Ponesite ono što vam treba za lagan prelazak:",
