    "info.process": "Бронюйте онлайн за кілька кліків. Після оплати ви отримаєте лист-підтвердження з бронюванням. Ваш номерний знак зберігається для шлагбаума, тож завдяки розпізнаванню номерів ви після прибуття в'їжджаєте прямо до критого паркінгу — без квитка, який можна загубити.",
