    "info.guarantee": "Zermatt er bilfrit. Efterlad bilen ved Matterhorn Terminal i Täsch, og tag pendlertoget — det kører cirka hvert 20. minut og når Zermatt på omkring 12 minutter.",
    "info.process": "Book online med få klik. Efter betaling modtager du en bekræftelsesmail med din reservation. Din nummerplade registreres til bommen, så nummerpladegenkendelsen lader dig køre direkte ind i det overdækkede parkeringshus ved ankomst — ingen billet at miste.",
