    "book.dob": "Fødselsdato",
    "gh.title": "Parkeringsinfo",
    "gh.lead": "Alt hvad du behøver at vide om parkering ved Matterhorn Terminal i Täsch og om at nå det bilfrie Zermatt — hvordan du ankommer, oplader din elbil og hvordan pendlertoget fungerer.",
    "gh.banner": "Zermatt er bilfrit. Alle biler stopper i Täsch: parkér ved Matterhorn Terminal, og fortsæt med pendlertog eller taxa.",
    "gh.car.d": "Kør til Täsch ad dalvejen, parkér i den overdækkede terminal, og hop på toget. Rute og højdegrænse.",
    "gh.charging.d": "131 ladestationer ved terminalen. Reservér en ladeplads sammen med din plads, og oplad mens du er i Zermatt.",
    "gh.train.d": "Pendlertoget forbinder Täsch og Zermatt på cirka 12 minutter, omtrent hvert 20. minut. Billetter, køreplan og bagage.",
    "gh.bus.d": "Buspladser og et afsætningsområde ved terminalen samt hvordan grupper fortsætter til Zermatt. Hvad du skal aftale på forhånd.",
    "gh.reduced.d": "Tilgængelige pladser tæt på elevatorerne og trinfri adgang til pendlertogets perron.",
    "car.h1": "Ankomst med bil",
    "car.lead": "Sådan kører du til Matterhorn Terminal i Täsch, og hvor du efterlader bilen til Zermatt.",
    "car.p1": "Zermatt er bilfrit, så enhver biltur til Matterhorn ender i Täsch. Fra Rhône-dalen følger du kantonvejen op gennem Visp, St. Niklaus og Randa; Matterhorn Terminal ligger lige ved siden af Täsch station for enden af dalvejen. Sæt navigationen til »Matterhorn Terminal Täsch«, så føres du direkte til indkørslen.",
    "car.h2a": "Parkering ved terminalen",
    "car.p2": "Terminalen er et overdækket parkeringshus i flere etager med omkring 2.100 pladser. Ved onlinebooking gemmes din nummerplade, så bommen åbner automatisk ved ankomst, og du kører direkte til en plads — ingen papirbillet at gemme. Vælg »Parkering« for en almindelig plads eller »Parkering med ladestation«, hvis din bil skal oplades.",
    "car.callout": "book online, inden du kører. Din nummerplade genkendes ved bommen, så du springer betalingsautomaterne over både ind og ud.",
    "car.h2b": "Højdegrænsen",
    "car.p3": "Den maksimale køretøjshøjde er 2,30 meter, hvilket dækker almindelige biler, stationcars og de fleste SUV'er, når en tagboks er fjernet. Højere køretøjer og autocampere kan ikke bruge det overdækkede p-hus — siden busser og grupper viser alternativerne for overstore køretøjer.",
    "car.h2c": "Fra bilen til Zermatt",
    "car.p4": "Pendlertogets perron er to minutters gang fra parkeringshuset. Tog til det bilfrie Zermatt kører omtrent hvert 20. minut og tager cirka 12 minutter; taxaer og elektriske hotelshuttles henter også ved terminalen.",
    "car.f1k": "Parkering",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Pladser",
    "car.f2v": "≈ 2.100, overdækket",
    "car.f3k": "Maks. højde",
    "car.f3v": "2,30 m",
    "car.f4k": "Til Zermatt",
    "car.f4v": "Pendlertog, ≈ 12 min",
    "chg.h1": "Elbiler og opladning",
    "chg.lead": "Opladning af din elbil under besøget i Zermatt, og hvordan du reserverer en ladeplads.",
    "chg.p1": "Matterhorn Terminal er et af de største ladesteder i Alperne med 131 ladestationer indbygget i det overdækkede parkeringshus. Stationerne leverer op til 22 kW (AC) med fast kabel og Type 2-stik, så de fleste elbiler oplader bekvemt, mens du er oppe i Zermatt.",
    "chg.h2a": "Reservation af en ladeplads",
    "chg.p2": "Ved bookingen vælger du »Parkering med ladestation« i stedet for almindelig parkering. Det reserverer en plads ved siden af en lader under hele dit ophold, så du ikke skal lede efter en ledig enhed ved ankomst.",
    "chg.callout": "vælg »Parkering med ladestation« i første trin af bookingformularen for at sikre en lader til dine datoer.",
    "chg.h2b": "Betaling for energien",
    "chg.p3": "Din reservation dækker parkeringspladsen og ladepladsen. Den energi, du faktisk bruger, afregnes separat ved stationen via QR-kode — kreditkort, TWINT, Apple Pay og Google Pay accepteres — så du betaler kun for den strøm, du bruger.",
    "chg.f1k": "Stationer",
    "chg.f1v": "131, i p-huset",
    "chg.f2k": "Effekt",
    "chg.f2v": "op til 22 kW AC, Type 2",
    "chg.f3k": "Reservér",
    "chg.f3v": "»Parkering med ladestation«",
    "chg.f4k": "Energi",
    "chg.f4v": "Betales ved stationen via QR",
    "trn.h1": "Sådan når du Zermatt",
    "trn.lead": "Hvordan pendlertoget forbinder Täsch og det bilfrie Zermatt.",
    "trn.p1": "Da Zermatt forbyder biler med forbrændingsmotor, foregår den sidste del af rejsen med tog. Pendlertoget kører mellem Täsch og Zermatt fra tidlig morgen til sent om aftenen, omtrent hvert 20. minut, og tilbagelægger strækningen på cirka 12 minutter.",
    "trn.h2a": "Billetter og perron",
    "trn.p2": "Perronen ligger lige ved siden af parkeringshuset — ingen vej at krydse, med elevatorer og ramper ned til sporene. Køb pendlerbilletter i automaterne i terminalen eller i togappen; de er uafhængige af din parkeringsreservation.",
    "trn.callout": "hav din parkeringsbekræftelse på telefonen. Den er knyttet til din nummerplade, ikke til togbilletten, som du køber separat.",
    "trn.h2b": "Bagage og videre rejse",
    "trn.p3": "Der er bagagevogne på begge perroner, og mange hoteller i Zermatt sender en eltaxa for at møde gæster i Zermatt-enden. Læg lidt luft ind i højsæsonen, når tog og perroner er fyldte.",
    "trn.f1k": "Linje",
    "trn.f1v": "Täsch ⇄ Zermatt pendler",
    "trn.f2k": "Frekvens",
    "trn.f2v": "≈ hvert 20. min",
    "trn.f3k": "Rejsetid",
    "trn.f3v": "≈ 12 min",
    "trn.f4k": "Billetter",
    "trn.f4v": "Købes separat",
    "bus.h1": "Busser og grupper",
    "bus.lead": "Hvor busser holder ved terminalen, og hvordan grupper fortsætter til Zermatt.",
    "bus.p1": "Turistbusser bruger terminalen i Täsch ligesom biler — Zermatt selv kan ikke nås med bus. Der er markerede buspladser og et afsætningsområde ved siden af stationen, hvor en gruppe kan stå af, før bussen parkerer.",
    "bus.h2a": "Parkering af bussen",
    "bus.p2": "Busparkering aftales ved terminalen; for store grupper og længere ophold er det bedst at kontakte terminalen på forhånd, så en plads er klar ved ankomst. Vores onlineformular er beregnet til biler og elbiler og bruges derfor ikke til busser.",
    "bus.h2b": "Videre til Zermatt",
    "bus.p3": "Fra afsætningsområdet er der kun få skridt til pendlertogets perron. Gruppetogbilletter til Zermatt kan arrangeres på forhånd; afsæt ekstra tid til at få en hel bus fuld af passagerer og bagage om bord på toget.",
    "bus.f1k": "Busser",
    "bus.f1v": "Pladser ved terminalen",
    "bus.f2k": "Booking",
    "bus.f2v": "Aftales med terminalen",
    "bus.f3k": "Afsætning",
    "bus.f3v": "Ved siden af stationen",
    "bus.f4k": "Til Zermatt",
    "bus.f4v": "Med pendlertog",
    "red.h1": "Nedsat mobilitet og tilgængelighed",
    "red.lead": "Tilgængelig parkering ved terminalen og trinfri adgang til pendlertoget.",
    "red.p1": "Matterhorn Terminal er designet trinfrit. Tilgængelige parkeringspladser ligger tæt på elevatorerne, der fører dig direkte ned til pendlertogets perron uden trapper.",
    "red.h2a": "Parkering tæt på elevatorerne",
    "red.p2": "Reservér en almindelig plads online på sædvanlig vis; har du et handicapparkeringskort, så parkér ved ankomst på en markeret tilgængelig plads nær elevatorkernen. Takket være bommen med nummerpladegenkendelse er der ingen automat, du skal nå fra bilen.",
    "red.h2b": "På toget og ind i Zermatt",
    "red.p3": "Elevatorer og ramper forbinder parkeringshuset med perronen, og pendlertogene medtager kørestole. I Zermatt kan der bestilles eltaxaer til at fortsætte til dit hotel. Medbring det, du har brug for til en gnidningsfri overgang:",
    "red.li1": "Din parkeringsbekræftelse (knyttet til din nummerplade)",
    "red.li2": "Et gyldigt handicapparkeringskort til de tilgængelige pladser",
    "red.f1k": "Adgang",
    "red.f1v": "Trinfri, elevatorer til perron",
    "red.f2k": "Pladser",
    "red.f2v": "Tilgængelige pladser ved elevatorerne",
    "red.f3k": "Tog",
    "red.f3v": "Kørestolsvenligt pendlertog",
    "red.f4k": "Medbring",
    "red.f4v": "Bekræftelse + handicapkort",
    "book.cardTitle": "Book din plads i Täsch",
    "book.arrivalDate": "Ankomstdato",
    "book.departureDate": "Afrejsedato"
