    "car.p1": "Zermatt er bilfritt, så enhver biltur til Matterhorn ender i Täsch. Fra Rhône-dalen følger du kantonveien oppover gjennom Visp, St. Niklaus og Randa; Matterhorn Terminal ligger rett ved siden av Täsch stasjon i enden av dalveien. Sett navigasjonen til «Matterhorn Terminal Täsch», så føres du rett til innkjørselen.",
