    "info.title": "Park edin ve Zermatt'a geçin",
    "info.guarantee": "Zermatt otomobilsizdir. Aracınızı Täsch'teki Matterhorn Terminal'de bırakın ve mekik trene binin — yaklaşık 20 dakikada bir kalkar ve Zermatt'a yaklaşık 12 dakikada ulaşır.",
    "info.process": "Birkaç tıklamayla çevrimiçi rezervasyon yapın. Ödemenin ardından rezervasyonunuzu içeren bir onay e-postası alırsınız. Plakanız bariyer için kaydedilir; böylece plaka tanıma sayesinde varışta doğrudan kapalı otoparka girersiniz — kaybedilecek bir bilet yok.",
    "info.extra": "Terminalde yaklaşık 2.100 kapalı yer ve 131 şarj istasyonu bulunur. Elektrikli aracınız için bir şarj yeri ayırtmak üzere rezervasyon sırasında «Şarj istasyonlu otopark» seçeneğini seçin.",
