    "book.dob": "Doğum tarihi",
    "gh.title": "Otopark bilgileri",
    "gh.lead": "Täsch'teki Matterhorn Terminal'de park etme ve otomobilsiz Zermatt'a ulaşma hakkında bilmeniz gereken her şey — nasıl gelinir, elektrikli aracınızı nasıl şarj edersiniz ve mekik tren nasıl çalışır.",
    "gh.banner": "Zermatt otomobilsizdir. Her araç Täsch'te durur: Matterhorn Terminal'de park edin ve mekik tren ya da taksiyle devam edin.",
    "gh.car.d": "Vadi yolundan Täsch'e gelin, kapalı terminalde park edin ve trene binin. Güzergah ve yükseklik sınırı.",
    "gh.charging.d": "Terminalde 131 şarj istasyonu. Yerinizle birlikte bir şarj yeri ayırtın ve Zermatt'tayken şarj edin.",
    "gh.train.d": "Mekik tren Täsch ile Zermatt'ı yaklaşık 12 dakikada, yaklaşık 20 dakikada bir bağlar. Biletler, tarife ve bagaj.",
    "gh.bus.d": "Terminalde otobüs yerleri ve iniş alanı; ayrıca grupların Zermatt'a nasıl devam ettiği. Önceden neyi ayarlamalısınız.",
    "gh.reduced.d": "Asansörlere yakın erişilebilir yerler ve mekik tren peronuna basamaksız erişim.",
    "car.h1": "Arabayla varış",
    "car.lead": "Täsch'teki Matterhorn Terminal'e nasıl gidilir ve Zermatt için arabayı nereye bırakırsınız.",
    "car.p1": "Zermatt otomobilsizdir, bu yüzden Matterhorn'a yapılan her kara yolculuğu Täsch'te biter. Rhône vadisinden kanton yolunu izleyerek Visp, St. Niklaus ve Randa üzerinden yukarı çıkarsınız; Matterhorn Terminal, vadi yolunun sonunda Täsch istasyonunun hemen yanındadır. Navigasyonu «Matterhorn Terminal Täsch» olarak ayarlayın, sizi doğrudan girişe götürür.",
    "car.h2a": "Terminalde park etme",
    "car.p2": "Terminal, yaklaşık 2.100 yerli, çok katlı kapalı bir otoparktır. Çevrimiçi rezervasyonda plakanız kaydedilir; böylece varışta bariyer otomatik açılır ve doğrudan bir yere gidersiniz — saklanacak kağıt bilet yok. Standart bir yer için «Otopark», aracınızın şarj olması gerekiyorsa «Şarj istasyonlu otopark» seçin.",
    "car.callout": "yola çıkmadan önce çevrimiçi rezervasyon yapın. Plakanız bariyerde tanınır; böylece giriş ve çıkışta ödeme makinelerini atlarsınız.",
    "car.h2b": "Yükseklik sınırı",
    "car.p3": "Araçlar için maksimum yükseklik 2,30 metredir; bu, tavan kutusu çıkarıldığında sıradan otomobilleri, station wagon'ları ve çoğu SUV'yi kapsar. Daha yüksek araçlar ve karavanlar kapalı otoparkı kullanamaz — otobüsler ve gruplar sayfası büyük araçlar için alternatifleri gösterir.",
    "car.h2c": "Arabadan Zermatt'a",
    "car.p4": "Mekik tren peronu otoparka iki dakika yürüme mesafesindedir. Otomobilsiz Zermatt'a giden trenler yaklaşık 20 dakikada bir kalkar ve yaklaşık 12 dakika sürer; taksiler ve elektrikli otel servisleri de terminalden yolcu alır.",
    "car.f1k": "Otopark",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "Yerler",
    "car.f2v": "≈ 2.100, kapalı",
    "car.f3k": "Maks. yükseklik",
    "car.f3v": "2,30 m",
    "car.f4k": "Zermatt'a",
    "car.f4v": "Mekik tren, ≈ 12 dk",
    "chg.h1": "Elektrikli araçlar ve şarj",
    "chg.lead": "Zermatt ziyaretiniz sırasında elektrikli aracınızı şarj etme ve bir şarj yeri ayırtma.",
    "chg.p1": "Matterhorn Terminal, kapalı otoparka yerleştirilmiş 131 şarj istasyonuyla Alpler'in en büyük şarj noktalarından biridir. İstasyonlar sabit kablo ve Type 2 soketle 22 kW'a (AC) kadar güç verir; böylece çoğu elektrikli araç siz Zermatt'tayken rahatça şarj olur.",
    "chg.h2a": "Bir şarj yeri ayırtma",
    "chg.p2": "Rezervasyon sırasında standart otopark yerine «Şarj istasyonlu otopark» seçin. Bu, tüm konaklamanız boyunca bir şarj cihazının yanında bir yer ayırır; böylece varışta boş bir ünite aramanız gerekmez.",
    "chg.callout": "tarihleriniz için bir şarj cihazı garantilemek amacıyla rezervasyon formunun ilk adımında «Şarj istasyonlu otopark»ı seçin.",
    "chg.h2b": "Enerjinin ödenmesi",
    "chg.p3": "Rezervasyonunuz otopark yerini ve şarj yerini kapsar. Gerçekte çektiğiniz enerji, istasyonda QR koduyla ayrıca faturalandırılır — kredi kartı, TWINT, Apple Pay ve Google Pay kabul edilir — böylece yalnızca kullandığınız elektriği ödersiniz.",
    "chg.f1k": "İstasyonlar",
    "chg.f1v": "131, otoparkta",
    "chg.f2k": "Güç",
    "chg.f2v": "22 kW AC'ye kadar, Type 2",
    "chg.f3k": "Ayırt",
    "chg.f3v": "«Şarj istasyonlu otopark»",
    "chg.f4k": "Enerji",
    "chg.f4v": "İstasyonda QR ile ödenir",
    "trn.h1": "Zermatt'a ulaşım",
    "trn.lead": "Mekik trenin Täsch ile otomobilsiz Zermatt'ı nasıl bağladığı.",
    "trn.p1": "Zermatt içten yanmalı araçları yasakladığı için yolculuğun son kısmı trenledir. Mekik tren, sabahın erken saatlerinden gece geç saatlere kadar Täsch ile Zermatt arasında yaklaşık 20 dakikada bir çalışır ve mesafeyi yaklaşık 12 dakikada kat eder.",
    "trn.h2a": "Biletler ve peron",
    "trn.p2": "Peron otoparkın hemen yanındadır — karşıdan karşıya geçilecek yol yok, raylara inen asansörler ve rampalar var. Mekik biletlerini terminaldeki makinelerden veya demiryolu uygulamasından alın; bunlar otopark rezervasyonunuzdan bağımsızdır.",
    "trn.callout": "otopark onayınızı telefonunuzda bulundurun. Bu, ayrıca satın aldığınız tren biletine değil, plakanıza bağlıdır.",
    "trn.h2b": "Bagaj ve devam yolculuğu",
    "trn.p3": "Her iki peronda da bagaj arabaları vardır ve Zermatt'taki birçok otel, misafirleri Zermatt tarafında karşılamak için elektrikli taksi gönderir. Trenlerin ve peronların kalabalık olduğu yoğun sezonda biraz pay bırakın.",
    "trn.f1k": "Hat",
    "trn.f1v": "Täsch ⇄ Zermatt mekik",
    "trn.f2k": "Sıklık",
    "trn.f2v": "≈ 20 dakikada bir",
    "trn.f3k": "Yolculuk",
    "trn.f3v": "≈ 12 dk",
    "trn.f4k": "Biletler",
    "trn.f4v": "Ayrı satın alınır",
    "bus.h1": "Otobüsler ve gruplar",
    "bus.lead": "Otobüslerin terminalde nerede durduğu ve grupların Zermatt'a nasıl devam ettiği.",
    "bus.p1": "Tur otobüsleri Täsch'teki terminali tıpkı otomobiller gibi kullanır — Zermatt'ın kendisine otobüsle ulaşılamaz. İstasyonun yanında işaretli otobüs yerleri ve otobüs park etmeden önce bir grubun inebileceği bir iniş alanı vardır.",
    "bus.h2a": "Otobüsü park etme",
    "bus.p2": "Otobüs parkı terminalde ayarlanır; büyük gruplar ve daha uzun konaklamalar için varışta bir yerin hazır olması amacıyla terminalle önceden iletişime geçmek en iyisidir. Çevrimiçi formumuz otomobiller ve elektrikli otomobiller için tasarlanmıştır, bu yüzden otobüsler için kullanılmaz.",
    "bus.h2b": "Zermatt'a devam",
    "bus.p3": "İniş alanından mekik tren peronuna birkaç adım vardır. Zermatt'a grup tren biletleri önceden ayarlanabilir; bir otobüs dolusu yolcu ve bagajı trene bindirmek için ek süre bırakın.",
    "bus.f1k": "Otobüsler",
    "bus.f1v": "Terminalde yerler",
    "bus.f2k": "Rezervasyon",
    "bus.f2v": "Terminalle kararlaştırılır",
    "bus.f3k": "İniş",
    "bus.f3v": "İstasyonun yanında",
    "bus.f4k": "Zermatt'a",
    "bus.f4v": "Mekik trenle",
    "red.h1": "Kısıtlı hareketlilik ve erişilebilirlik",
    "red.lead": "Terminalde erişilebilir otopark ve mekik trene basamaksız erişim.",
    "red.p1": "Matterhorn Terminal basamaksız tasarlanmıştır. Erişilebilir otopark yerleri, sizi merdivensiz doğrudan mekik tren peronuna indiren asansörlerin yakınındadır.",
    "red.h2a": "Asansörlere yakın park etme",
    "red.p2": "Her zamanki gibi çevrimiçi standart bir yer ayırtın; engelli park kartınız varsa varışta asansör çekirdeğinin yakınındaki işaretli erişilebilir bir yere park edin. Plaka tanımalı bariyer sayesinde arabadan ulaşmanız gereken bir makine yoktur.",
    "red.h2b": "Trene ve Zermatt'a",
