    "gh.title": "停车信息",
    "gh.lead": "关于在 Täsch 的 Matterhorn Terminal 停车以及前往无车 Zermatt 的一切须知——如何抵达、如何为电动车充电，以及接驳列车如何运作。",
    "gh.banner": "Zermatt 是无车小镇。所有车辆都在 Täsch 停下：把车停在 Matterhorn Terminal，再乘坐接驳列车或出租车继续前行。",
    "gh.car.d": "沿山谷公路抵达 Täsch，停在有顶终端并搭乘列车。路线与限高。",
    "gh.charging.d": "终端设有 131 个充电桩。预订车位时一并预留充电车位，在 Zermatt 期间即可充电。",
    "gh.train.d": "接驳列车约 12 分钟连接 Täsch 与 Zermatt，约每 20 分钟一班。车票、时刻表与行李。",
    "gh.bus.d": "终端的大巴车位与落客区，以及团队如何继续前往 Zermatt。需提前安排的事项。",
    "gh.reduced.d": "靠近电梯的无障碍车位，以及通往接驳列车站台的无台阶通道。",
    "car.h1": "自驾抵达",
    "car.lead": "如何驾车前往 Täsch 的 Matterhorn Terminal，以及前往 Zermatt 时把车停在哪里。",
    "car.p1": "Zermatt 是无车小镇，因此每一次驶向马特洪峰的自驾都止于 Täsch。从罗讷河谷出发，沿州级公路经 Visp、St. Niklaus 和 Randa 向上行驶；Matterhorn Terminal 就位于山谷公路尽头的 Täsch 车站旁。将导航设为“Matterhorn Terminal Täsch”，即可直接抵达入口。",
    "car.h2a": "在终端停车",
    "car.p2": "终端是一座约有 2,100 个车位的多层有顶停车楼。在线预订时会记录您的车牌，抵达时道闸自动打开，直接驶向车位——无需保留纸质取票。普通车位选择“停车”，如需充电则选择“带充电桩的停车位”。",
    "car.callout": "出发前在线预订。您的车牌会在道闸处被识别，进出时都可省去缴费机。",
    "car.h2b": "限高",
    "car.p3": "车辆最大高度为 2.30 米，可容纳普通轿车、旅行车以及大多数拆下车顶箱后的 SUV。更高的车辆和房车无法使用有顶停车楼——大巴与团队页面列出了超大车辆的替代方案。",
    "car.h2c": "从车到 Zermatt",
    "car.p4": "接驳列车站台距停车楼步行两分钟。前往无车 Zermatt 的列车约每 20 分钟一班，约 12 分钟；出租车和酒店电动接驳车也在终端接客。",
    "car.f1k": "停车场",
    "car.f1v": "Matterhorn Terminal, Täsch",
