    "chg.h1": "电动车与充电",
    "chg.lead": "在游览 Zermatt 期间为电动车充电，以及如何预留充电车位。",
    "chg.p1": "Matterhorn Terminal 是阿尔卑斯山最大的充电点之一，有顶停车楼内设有 131 个充电桩。充电桩提供最高 22 kW（交流）功率，配固定电缆和 Type 2 插头，多数电动车都能在您上山游览 Zermatt 时从容充电。",
    "chg.h2a": "预留充电车位",
