    "chg.callout": "在预订表单的第一步选择“带充电桩的停车位”，即可为您的日期锁定一个充电桩。",
    "chg.h2b": "电费支付",
    "chg.p3": "您的预订涵盖停车位和充电车位。实际使用的电量在充电桩处通过二维码单独结算——支持信用卡、TWINT、Apple Pay 和 Google Pay——因此您只需为所用电量付费。",
