    "gh.title": "주차 안내",
    "gh.lead": "Täsch 의 Matterhorn Terminal 주차와 차 없는 Zermatt 로 가는 방법에 대한 모든 것 — 오는 방법, 전기차 충전, 그리고 셔틀 열차의 작동 방식.",
    "gh.banner": "Zermatt 는 차량이 없는 곳입니다. 모든 차는 Täsch 에서 멈춥니다. Matterhorn Terminal 에 주차하고 셔틀 열차나 택시로 이동하세요.",
    "gh.car.d": "계곡 도로를 따라 Täsch 로 와서 실내 터미널에 주차하고 열차에 오르세요. 경로와 높이 제한.",
    "gh.charging.d": "터미널에 131개의 충전소. 자리와 함께 충전 공간을 예약하고 Zermatt 에 있는 동안 충전하세요.",
