    "gh.bus.d": "터미널의 버스 자리와 하차 구역, 그리고 단체가 Zermatt 로 이동하는 방법. 미리 준비할 사항.",
    "gh.reduced.d": "엘리베이터 가까이의 장애인 주차 자리와 셔틀 열차 승강장으로의 무단차 접근.",
    "car.h1": "자동차로 도착",
    "car.lead": "Täsch 의 Matterhorn Terminal 로 가는 방법과 Zermatt 를 위해 차를 둘 곳.",
    "car.p1": "Zermatt 는 차량이 없는 곳이므로 마터호른으로 가는 모든 자동차 여행은 Täsch 에서 끝납니다. 론 계곡에서 주 도로를 따라 Visp, St. Niklaus, Randa 를 거쳐 올라오면, Matterhorn Terminal 은 계곡 도로 끝의 Täsch 역 바로 옆에 있습니다. 내비게이션을 'Matterhorn Terminal Täsch' 로 설정하면 입구까지 곧바로 안내합니다.",
    "car.h2a": "터미널 주차",
    "car.p2": "터미널은 약 2,100대 규모의 다층 실내 주차장입니다. 온라인 예약 시 번호판이 저장되어, 도착하면 차단기가 자동으로 열리고 곧바로 자리로 이동합니다 — 보관할 종이 티켓이 없습니다. 일반 자리는 '주차'를, 충전이 필요하면 '충전소 포함 주차'를 선택하세요.",
    "car.callout": "출발 전에 온라인으로 예약하세요. 번호판이 차단기에서 인식되어 입출차 시 요금 정산기를 건너뜁니다.",
    "car.h2b": "높이 제한",
    "car.p3": "차량 최대 높이는 2.30미터로, 일반 승용차, 왜건, 그리고 루프 박스를 떼어낸 대부분의 SUV 가 해당됩니다. 더 높은 차량과 캠핑카는 실내 주차장을 이용할 수 없습니다 — 버스 및 단체 페이지에서 대형 차량 대안을 확인하세요.",
    "car.h2c": "차에서 Zermatt 로",
    "car.p4": "셔틀 열차 승강장은 주차장에서 도보 2분 거리입니다. 차 없는 Zermatt 로 가는 열차는 약 20분 간격으로 운행하며 약 12분이 걸립니다. 택시와 호텔 전기 셔틀도 터미널에서 승객을 태웁니다.",
    "car.f1k": "주차장",
    "car.f1v": "Matterhorn Terminal, Täsch",
    "car.f2k": "자리",
    "car.f2v": "≈ 2,100, 실내",
    "car.f3k": "최대 높이",
    "car.f3v": "2.30 m",
    "car.f4k": "Zermatt 로",
    "car.f4v": "셔틀 열차, ≈ 12분",
    "chg.h1": "전기차와 충전",
    "chg.lead": "Zermatt 방문 중 전기차 충전과 충전 공간 예약 방법.",
    "chg.p1": "Matterhorn Terminal 은 알프스 최대 규모의 충전 장소 중 하나로, 실내 주차장 안에 131개의 충전소가 있습니다. 충전소는 고정 케이블과 Type 2 플러그로 최대 22 kW(AC)를 제공하여, Zermatt 에 올라가 있는 동안 대부분의 전기차가 여유롭게 충전됩니다.",
    "chg.h2a": "충전 공간 예약",
    "chg.p2": "예약 시 일반 주차 대신 '충전소 포함 주차'를 선택하세요. 그러면 체류 기간 내내 충전기 옆 자리가 예약되어, 도착 시 빈 충전기를 찾을 필요가 없습니다.",
    "chg.callout": "예약 양식의 첫 단계에서 '충전소 포함 주차'를 선택해 원하는 날짜에 충전기를 확보하세요.",
    "chg.h2b": "전력 요금 결제",
    "chg.p3": "예약에는 주차 공간과 충전 공간이 포함됩니다. 실제 사용한 전력은 충전소에서 QR 코드로 별도 결제됩니다 — 신용카드, TWINT, Apple Pay, Google Pay 를 지원합니다 — 따라서 사용한 전기만큼만 지불합니다.",
    "chg.f1k": "충전소",
    "chg.f1v": "131개, 주차장 내",
    "chg.f2k": "출력",
    "chg.f2v": "최대 22 kW AC, Type 2",
    "chg.f3k": "예약",
    "chg.f3v": "'충전소 포함 주차'",
    "chg.f4k": "전력",
    "chg.f4v": "충전소에서 QR 결제",
    "trn.h1": "Zermatt 가는 방법",
    "trn.lead": "셔틀 열차가 Täsch 와 차 없는 Zermatt 를 어떻게 연결하는가.",
    "trn.p1": "Zermatt 는 내연기관 차량을 금지하므로 여정의 마지막 구간은 열차입니다. 셔틀 열차는 이른 아침부터 늦은 밤까지 Täsch 와 Zermatt 사이를 약 20분 간격으로 운행하며, 이 거리를 약 12분에 주파합니다.",
    "trn.h2a": "티켓과 승강장",
    "trn.p2": "승강장은 주차장 바로 옆에 있어 — 건너야 할 도로가 없고, 선로로 내려가는 엘리베이터와 경사로가 있습니다. 셔틀 티켓은 터미널의 발권기나 철도 앱에서 구입하세요. 주차 예약과는 별개입니다.",
    "trn.callout": "주차 확인을 휴대폰에 보관하세요. 이는 별도로 구입하는 열차 티켓이 아니라 번호판에 연결되어 있습니다.",
    "trn.h2b": "수하물과 이후 이동",
    "trn.p3": "양쪽 승강장에 수하물 카트가 있으며, Zermatt 의 많은 호텔이 Zermatt 쪽에서 손님을 맞이하기 위해 전기 택시를 보냅니다. 열차와 승강장이 붐비는 성수기에는 여유 시간을 두세요.",
    "trn.f1k": "노선",
    "trn.f1v": "Täsch ⇄ Zermatt 셔틀",
    "trn.f2k": "배차",
    "trn.f2v": "≈ 20분마다",
    "trn.f3k": "소요 시간",
    "trn.f3v": "≈ 12분",
    "trn.f4k": "티켓",
    "trn.f4v": "별도 구입",
    "bus.h1": "버스와 단체",
    "bus.lead": "버스가 터미널의 어디에 정차하는지와 단체가 Zermatt 로 이동하는 방법.",
    "bus.p1": "관광버스도 승용차와 마찬가지로 Täsch 의 터미널을 이용합니다 — Zermatt 자체는 버스로 갈 수 없습니다. 역 옆에 표시된 버스 자리와 하차 구역이 있어, 버스가 주차하기 전에 단체가 내릴 수 있습니다.",
    "bus.h2a": "버스 주차",
    "bus.p2": "버스 주차는 터미널에서 마련합니다. 대규모 단체나 장기 체류의 경우, 도착 시 자리가 준비되도록 터미널에 미리 연락하는 것이 가장 좋습니다. 저희 온라인 양식은 승용차와 전기차를 위한 것이므로 버스에는 사용되지 않습니다.",
    "bus.h2b": "Zermatt 로 계속",
    "bus.p3": "하차 구역에서 셔틀 열차 승강장까지는 몇 걸음입니다. Zermatt 행 단체 열차 티켓은 미리 마련할 수 있습니다. 버스 한 대 분량의 승객과 수하물을 열차에 태우려면 여유 시간을 두세요.",
