    "red.p1": "Matterhorn Terminal 은 단차 없이 설계되었습니다. 접근 가능한 주차 자리는 엘리베이터 가까이에 있어, 계단 없이 셔틀 열차 승강장까지 곧바로 내려갈 수 있습니다.",
