    "red.p2": "평소처럼 온라인으로 일반 자리를 예약하세요. 장애인 주차 표지가 있으면 도착 시 엘리베이터 코어 근처의 표시된 접근 가능 자리에 주차하세요. 번호판 인식 차단기 덕분에 차에서 조작해야 할 기계가 없습니다.",
